export type ParsedWithdrawFromProtocolInstruction<
  TProgram extends string = typeof HELIO_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    owner: TAccountMetas[0];
    config: TAccountMetas[1];
    reserveState: TAccountMetas[2];
    stableMint: TAccountMetas[3];
    /**
     * CHECK / SAFETY: program PDA (no discriminator); address constrained by the
     * `seeds = [AUTHORITY_SEED, owner]` derivation and used only as the token
     * authority / CPI signer (same as `withdraw_stable.rs::reserve_authority`).
     */
    reserveAuthority: TAccountMetas[4];
    /** The reserve's stable vault (destination of the withdrawn underlying). */
    stableVault: TAccountMetas[5];
    /**
     * CHECK / SAFETY: foreign program state, intentionally not deserialized. The
     * handler enforces `protocol_vault.owner == pinned protocol program` and
     * binds `protocol_token_vault` / `protocol_lp_mint` to its derived PDAs.
     */
    protocolVault: TAccountMetas[6];
    /** Validated in the handler to be the `[b"token_vault", protocol_vault]` PDA. */
    protocolTokenVault: TAccountMetas[7];
    /** Validated in the handler to be the `[b"lp_mint", protocol_vault]` PDA. */
    protocolLpMint: TAccountMetas[8];
    /** The reserve authority's LP token account (source of the LP to burn). */
    reserveLpAccount: TAccountMetas[9];
    /**
     * CHECK / SAFETY: pinned in the handler to the active protocol's program id
     * via `resolve_protocol_program`; only used as the CPI target program.
     */
    protocolProgram: TAccountMetas[10];
    tokenProgram: TAccountMetas[11];
  };
  data: WithdrawFromProtocolInstructionData;
};

export function parseWithdrawFromProtocolInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedWithdrawFromProtocolInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      owner: getNextAccount(),
      config: getNextAccount(),
      reserveState: getNextAccount(),
      stableMint: getNextAccount(),
      reserveAuthority: getNextAccount(),
      stableVault: getNextAccount(),
      protocolVault: getNextAccount(),
      protocolTokenVault: getNextAccount(),
      protocolLpMint: getNextAccount(),
      reserveLpAccount: getNextAccount(),
      protocolProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getWithdrawFromProtocolInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
